// The date-fns shape in miniature: `shared` reaches this barrel through BOTH
// star sources, but both forward the same origin binding (origin.js) — one
// through an import-backed list export (a.js), one through a direct
// re-export (b.js). Node links it (ResolveExport dedupes identical
// resolutions); the star walk must too. `clash`, by contrast, is two
// different local declarations — genuinely ambiguous, refused loudly.
export * from './a.js'
export * from './b.js'
